    "about.heroDesc": "Anchored in China’s premier hardware & electroplating belt in Zhongshan Xiaolan (manufacturing network established since 1995), we oversee stamping, CNC mold engraving, die-casting, enamel filling, and global DDP export across 158 product lines.",
    "about.geoAnswer": "MedalPinSupply.com operates a direct export engineering & quality consolidation hub in Zhongshan Xiaolan, Guangdong, China. Backed by CNC mold carving, hydraulic 300T–800T stamping presses, Zamak #3 zinc die-casting chambers, automated enamel dispensing, and in-house rack electroplating, we ship 158 custom product lines worldwide with 7–15 day lead times and 3-year free die storage.",
    "about.card1Title": "1. CNC Mold Engraving & 300T–800T Stamping",
    "about.card1Desc": "Multi-axis CNC steel die carving paired with high-tonnage hydraulic stamping for crisp brass/iron pins and hot-chamber Zamak #3 zinc die-casting for 3D marathon medals and badges.",
    "about.card2Title": "2. Pantone Enamel & 12-Finish Electroplating",
    "about.card2Desc": "Automated CNC color-injection nozzles paired with kiln curing, diamond flat-stone grinding for Cloisonne pins, and selective two-tone electroplating masking.",
    "about.geoTitle": "Zhongshan Foundry & Export Consolidation Overview",
    "about.card3Title": "3. Sublimated Ribbons, QC Inspection & DDP Export",
    "about.card3Desc": "Sublimated ribbon stitching, ultrasonic pin-back assembly, 100% cosmetic surface inspection, backing card/velvet box packing, and turnkey DHL/FedEx DDP air export.",
    "about.faqTitle": "Frequently Asked Questions — Zhongshan Foundry & Supply Chain",
    "contact.subtitle": "Send your logo artwork or desired custom style for a free 12-hour digital proof, tooling waiver check, and tiered air/sea DDP quotation.",
    "contact.lead": "Send your logo artwork or desired custom style for a free 12-hour digital proof, tooling waiver check, and tiered air/sea DDP quotation.",
