    "guide.authorBio": "Verfasst von unseren Prägewerkzeug-Ingenieuren in Zhongshan Xiaolan. Unser Team leitet CNC-3D-Gravuren, Pantone-Farbmischungen, selektive Zweifach-Galvanik und CPSIA/EN71-3 Qualitätsprüfungen für alle 158 Produktlinien.",
