    "about.heroTitle": "Direkthersteller für Pins, Medaillen & Coins aus Zhongshan Xiaolan",
    "about.heroDesc": "Im Herzen des chinesischen Präge- und Galvanik-Clusters Zhongshan Xiaolan fertigen wir auf Basis eines seit 1995 etablierten Werksnetzwerks alle 158 Produktlinien vom Werkzeugbau bis zum weltweiten DDP-Export.",
    "about.geoAnswer": "MedalPinSupply.com betreibt ein direktes Export- und Qualitätszentrum in Zhongshan Xiaolan, China. Mit CNC-Formenbau, 300T–800T Prägepressen, Zamak #3 Druckguss, Emaille-Automaten und hauseigener Galvanik liefern wir 158 Produktlinien weltweit in 7–15 Tagen inkl. 3 Jahre gratis Formlagerung.",
    "about.card1Title": "1. CNC-Formenbau & 300T–800T Prägepressen",
    "about.card1Desc": "Mehrachsige CNC-Stahlgravuren kombiniert mit Hochdruckpressen für präzise Messing-/Eisen-Pins sowie Warmkammer-Zamak-Druckguss für 3D-Medaillen und Abzeichen.",
    "about.card2Title": "2. Pantone-Emaille & 12 Galvanik-Finishes",
    "about.card2Desc": "Automatisierte CNC-Farbdosierung mit Brennofen-Härtung, Diamantschliff für Hartemaille sowie selektiver Abdecktechnik für Bicolor-Galvanik.",
