    "about.card3Title": "3. Bandkonfektionierung, 100%-Prüfung & DDP-Versand",
    "about.card3Desc": "Sublimationsband-Vernähung, Ultraschall-Montage, 100% Oberflächen-Endkontrolle, Etui-/Kartenverpackung sowie direkter DHL/FedEx DDP-Luftexpress.",
