    "brand.heroTitle": "Émaux, Sculpture 3D & 12 Finitions de Placage Métallique",
    "brand.heroDesc": "Comparez Émail Dur, Émail Doux, Gravure Photochimique, Offset CMJN + Époxy, Zinc 3D, Bi-ton et 12 placages résistants au ternissement.",
    "brand.geoTitle": "Synthèse Technique: Émaux, Outillages & Placages",
    "brand.geoAnswer": "Nos ingénieurs orientent entre Émail Dur (surface lisse affleurante), Émail Doux (reliefs tactiles 15–25% moins cher), Gravure Photochimique (lignes fines 0,8mm), Offset CMJN (dégradés photo) et Zinc 3D (médailles et pièces). Matrices 2D offertes dès 500 pcs et moules 3D dès 1 000 pcs.",
