    "pkg.heroTitle": "Coffrets Velours, Cartons 400g & Capsules Acryliques",
    "pkg.heroDesc": "Valorisez vos pins, pièces Challenge et boutons de manchette avec des cartes de présentation, capsules acryliques et écrins en velours marqués à chaud.",
    "pkg.geoAnswer": "Les 158 créations sur mesure sont emballées en sachet individuel gratuit. Options: (1) Cartons 400g imprimés ou dorés à chaud (+0,12–0,22$/pc, MOQ 300), (2) Capsules rigides & pochettes PVC (+0,15–0,35$), (3) Écrins velours marqués à chaud pour médailles, pièces & boutons de manchette (+0,85–1,85$, MOQ 100).",
