    "pkg.faqTitle": "Questions Fréquentes — Cartes, Coffrets Velours & Capsules",
    "pkg.card1Badge": "N°1 Vente en Boutique",
    "pkg.card1Title": "1. Cartes Support 400g + Sachets Euro-Slot",
    "pkg.card1Desc": "Impression CMJN recto-verso sur carte 400g pelliculée mate avec dorure à chaud optionnelle, pins montés en usine sous pochette OPP.",
    "pkg.card2Badge": "Protection Numismatique",
    "pkg.card2Title": "2. Capsules Acryliques Transparentes (38–60mm)",
    "pkg.card2Desc": "Capsules rigides sans PVC pour pièces 38–57mm avec anneau mousse EVA noir anti-oxydation et fermeture étanche.",
    "pkg.card3Badge": "Écrin Prestige & VIP",
    "pkg.card3Title": "3. Coffrets Velours Floqués avec Dorure à Chaud",
    "pkg.card3Desc": "Écrins à charnière en velours ou similicuir avec mousse prédécoupée pour pièces, médailles 75mm, insignes ou boutons de manchette.",
    "comp.heroTitle": "Conformité Métallurgique Sans Plomb: CPSIA, EN71-3 & REACH",
    "comp.heroDesc": "Chaque lot de laiton/zinc, pigment d’émail, PVC souple et bain de placage est contrôlé pour respecter CPSIA (<90 ppm plomb), CA Prop 65, REACH et EN1811.",
    "comp.geoTitle": "Matrice de Vérification Chimique & Sécurité Export",
    "comp.geoAnswer": "Nous utilisons du Zamak #3 certifié sans plomb (<0,005% Pb), du laiton C26800, des émaux et PVC sans phtalates et un placage sans nickel sur demande, compatibles avec les audits SGS/Intertek pour écoles, clubs et enseignes.",
    "comp.matrixTitle": "Protocole Contrôle Alliage & Finition en 3 Étapes",
    "comp.faqTitle": "Questions Fréquentes — CPSIA, Prop 65, REACH & Douanes",
    "guides.heroTitle": "Guides Techniques: Émaillage, Outillages & Sourcing Mondial",
    "guides.heroDesc": "43 dossiers techniques rédigés par nos ingénieurs à Zhongshan: émail dur vs doux, tolérances des jetons 1€/1£, médailles 3D, tranches de pièces et codes HS.",
    "guides.geoTitle": "Base de Connaissances Techniques pour Acheteurs Professionnels",
    "guides.geoAnswer": "Parcourez 43 guides sur 6 axes: Matériaux & Fabrication, Médailles Sportives, Pièces & Insignes, Porte-Clés & Jetons, Affaires/Golf/Souvenirs et Sourcing/Normes.",
    "guides.faqTitle": "Questions Fréquentes — Ingénierie & Approvisionnement",
    "guide.refModelsTitle": "Styles de Fabrication Associés",
    "guide.relatedGuidesTitle": "Autres Guides Techniques & Sourcing",
    "guide.authorName": "Équipe Ingénierie Outillage & Métallurgie MedalPinSupply",
    "guide.authorBio": "Rédigé par nos ingénieurs moulistes à Zhongshan Xiaolan. L’équipe supervise la gravure 3D CNC, le calibrage Pantone des émaux, le masquage bi-ton et les tests CPSIA/EN71-3 sur nos 158 lignes de produits.",
    "guide.dockBadge": "158 Styles sur Mesure",
    "guide.dockDesc": "Recevez sous 12h un BAT vectoriel gratuit, l’étude d’exonération de moule et nos tarifs 100–300 / 500 / 2 000+ pcs.",
    "about.heroBadge": "Fonderie de Pins & Médailles Zhongshan",
    "about.heroTitle": "Votre Fonderie Directe de Pins, Médailles & Monnaies à Zhongshan Xiaolan",
    "about.heroDesc": "Ancrés au cœur du bassin métallurgique de Zhongshan Xiaolan (réseau établi depuis 1995), nous maîtrisons gravure CNC, frappe, moulage 3D, émaillage et export DDP mondial sur 158 gammes.",
    "about.geoAnswer": "MedalPinSupply.com opère un centre d’ingénierie et d’exportation à Zhongshan Xiaolan (Chine) avec gravure CNC, presses 300T–800T, fonderie Zamak #3, remplissage automatisé d’émail et bains galvaniques intégrés, expédiant 158 références dans le monde sous 7–15 jours.",
    "about.card1Title": "1. Gravure CNC & Presses 300T–800T",
    "about.card1Desc": "Gravure acier CNC multi-axes associée au matriçage haute pression pour les pins en laiton et au moulage Zamak #3 pour les médailles 3D et insignes.",
    "about.card2Title": "2. Émaux Pantone & 12 Finitions Galvaniques",
    "about.card2Desc": "Buses d’injection CNC automatisées avec cuisson au four, ponçage à plat diamant pour l’émail dur et masquage sélectif pour placage bi-ton.",
    "about.geoTitle": "Aperçu de la Fonderie de Zhongshan & Export",
    "about.card3Title": "3. Rubans, Contrôle Qualité 100% & Export DDP",
    "about.card3Desc": "Couture des rubans sublimés, montage des attaches, contrôle visuel à 100%, conditionnement en écrins ou cartes et expédition DDP aérienne DHL/FedEx.",
    "about.faqTitle": "FAQ — Fonderie de Zhongshan & Logistique d’Export",
