    "about.card1Desc": "Incisione CNC multiasse su acciaio abbinata a presse idrauliche per spille nitide e pressofusione Zamak #3 per medaglie 3D e distintivi.",
    "about.card2Title": "2. Smalti Pantone e 12 Finiture Galvaniche",
    "about.card2Desc": "Ugelli CNC automatici con cottura in forno, levigatura piana al diamante per smalto duro e mascheratura selettiva bicolore.",
