    "pkg.geoAnswer": "전 158종 기본 개별 폴리백 포장($0) 제공. 옵션: (1) 400g 인쇄 백킹 카드 (+$0.12–$0.22), (2) 투명 코인 캡슐/PVC 파우치 (+$0.15–$0.35), (3) 금박 로고 벨벳 선물 박스 (+$0.85–$1.85, MOQ 100).",
