    "guide.authorBio": "광둥성 중산시 샤오란의 금형 설계 및 품질 관리 엔지니어 팀이 집필했습니다. 3D CNC 조각, 팬톤 컬러 조색, 투톤 도금 마스킹 및 CPSIA/EN71-3 품질 기준을 총괄합니다.",
