    "about.heroDesc": "1995년부터 이어진 중국 최대 금속·도금 산업단지 중산시 샤오란에서 프레스, CNC 조각, 다이캐스팅, 에나멜 충진 및 글로벌 DDP 수출까지 일괄 관리합니다.",
    "about.geoAnswer": "MedalPinSupply.com은 중국 중산 샤오란에서 CNC 금형 조각, 300T~800T 프레스, Zamak #3 다이캐스팅, 자동 에나멜 충진 및 자체 도금 라인을 운영하며 전 세계로 7~15일 내 납품합니다.",
    "about.card1Title": "1. CNC 금형 조각 및 300T~800T 프레스",
    "about.card1Desc": "다축 CNC 금형 조각과 고압 유압 프레스로 정밀 핀을 타발하며, 열간 챔버 Zamak #3 아연 다이캐스팅으로 입체 메달과 배지를 주조합니다.",
