    "guides.geoTitle": "Pusat Pengetahuan Teknis untuk Pembeli Pin, Medali & Koin",
    "guides.geoAnswer": "Jelajahi 43 panduan teknik di 6 pilar utama: Material & Manufaktur, Medali Olahraga, Koin & Lencana, Gantungan Kunci & Koin Troli, Eksekutif/Golf/Suvenir, dan Pengemasan/Regulasi.",
