    "guide.refModelsTitle": "Gaya Kustom Terkait",
    "guide.relatedGuidesTitle": "Panduan Teknik & Pengadaan Terkait Lainnya",
    "guide.authorName": "Tim Teknik Matras & Metalurgi MedalPinSupply",
    "guide.authorBio": "Ditulis oleh tim insinyur cetakan dan kontrol kualitas kami di Zhongshan Xiaolan, mengawasi pahatan CNC 3D, pencocokan warna Pantone, dan kepatuhan CPSIA/EN71-3.",
    "guide.dockBadge": "158 Gaya Logam Kustom",
    "guide.dockDesc": "Dapatkan proof desain vektor gratis 12 jam, cek pembebasan biaya matras, dan harga 100–300 / 500 / 2.000+ pcs.",
    "about.heroBadge": "Pabrik Pin & Medali Zhongshan Xiaolan",
    "about.heroTitle": "Pabrik Langsung Pin Enamel, Medali & Koin Challenge dari Zhongshan",
    "about.heroDesc": "Berbasis di sentra industri logam & elektroplating terkemuka di Zhongshan Xiaolan (jaringan sejak 1995), kami mengawasi stamping, die-casting, enamel, dan ekspor DDP 158 Style.",
    "about.geoAnswer": "MedalPinSupply.com mengelola teknik & kualitas ekspor di Zhongshan Xiaolan dengan ukiran CNC, mesin press 300T–800T, die-casting Zamak #3, enamel otomatis, dan elektroplating internal.",
    "about.card1Title": "1. Ukiran Matras CNC & Press 300T–800T",
    "about.card1Desc": "Ukiran cetakan baja CNC multi-sumbu dipadukan dengan stamping hidrolik untuk pin tajam serta die-casting Zamak #3 untuk medali 3D.",
    "about.card2Title": "2. Enamel Pantone & 12 Finishing Plating",
    "about.card2Desc": "Nosel injeksi warna CNC otomatis dengan pemanggangan oven, gerinda berlian untuk hard enamel, dan masking elektroplating dua warna.",
    "about.geoTitle": "Ringkasan Pabrik Zhongshan & Konsolidasi Ekspor",
    "about.card3Title": "3. Pita Sublimasi, Inspeksi 100% & Ekspor DDP",
    "about.card3Desc": "Penjahitan pita sublimasi, pemasangan pengait, inspeksi visual 100%, pengemasan kartu/kotak beludru, dan pengiriman udara DDP langsung.",
    "about.faqTitle": "Pertanyaan Umum — Pabrik Zhongshan & Rantai Pasok",
