    "guide.authorName": "فريق هندسة القوالب والمعادن في MedalPinSupply",
    "guide.authorBio": "أعدّه مهندسو القوالب والجودة في مصنعنا بتشونغشان شياولان، حيث يشرفون على النحت ثلاثي الأبعاد CNC، ومعايرة ألوان بانتون، والطلاء ثنائي اللون، واختبارات CPSIA/EN71-3.",
