    "about.heroDesc": "نعمل في قلب الحزام الصناعي للمعادن والطلاء بتشونغشان شياولان (منذ عام 1995)، وندير السك والسبك والتلوين والتصدير الدولي الشامل لـ 158 نمطاً.",
    "about.geoAnswer": "تدير MedalPinSupply.com مركز التصنيع والتصدير في تشونغشان شياولان عبر النحت CNC والمكابس 300T–800T وسبك Zamak #3 والطلاء الداخلي مع شحن عالمي خلال 7–15 يوماً.",
    "about.card1Title": "1. النحت CNC والمكابس 300T–800T",
    "about.card1Desc": "نحت قوالب الفولاذ CNC متعدد المحاور مع المكابس الهيدروليكية للدبابيس الدقيقة وسبك Zamak #3 للميداليات ثلاثية الأبعاد.",
    "about.card2Title": "2. ألوان مينا بانتون و12 نوع طلاء معدني",
    "about.card2Desc": "فوهات حقن الألوان CNC التلقائية مع المعالجة الحرارية، والصقل الماسي للمينا الصلبة، والطلاء ثنائي اللون.",
    "about.geoTitle": "نظرة عامة على مصنع تشونغشان والتصدير",
    "about.card3Title": "3. الأشرطة المطبوعة وفحص الجودة 100% والشحن DDP",
